  1832  /* Opens file 'file_name' and reads each line as a flow_mod of the specified
  1833   * type (one of OFPFC_*).  Stores each flow_mod in '*fm', an array allocated
  1834   * on the caller's behalf, and the number of flow_mods in '*n_fms'.
  1835   *
   916  parse_int_string(const char *s, uint8_t *valuep, int field_width, char **tail)
   917  {
   918      unsigned long long int integer;
   919      int i;
   920
   921      if (!strncmp(s, "0x", 2) || !strncmp(s, "0X", 2)) {
   922          uint8_t *hexit_str;
   923          int len = 0;
   924          int val_idx;
   925          int err = 0;
   926
   927          s += 2;
   928          hexit_str = xmalloc(field_width * 2);
   929
   930          for (;;) {
   931              uint8_t hexit;
   932              bool ok;
   933
   934              s += strspn(s, " \t\r\n");
   935              hexit = hexits_value(s, 1, &ok);
   936              if (!ok) {
   937                  *tail = CONST_CAST(char *, s);
   938                  break;
   939              }
   940
   941              if (hexit != 0 || len) {
   942                  if (DIV_ROUND_UP(len + 1, 2) > field_width) {
   943                      err = ERANGE;
   944                      goto free;
   945                  }
   946
   947                  hexit_str[len] = hexit;
   948                  len++;
   949              }
   950              s++;
   951          }
   952
   953          val_idx = field_width;
   954          for (i = len - 1; i >= 0; i -= 2) {
   955              val_idx--;
   956              valuep[val_idx] = hexit_str[i];
   957              if (i > 0) {
   958                  valuep[val_idx] += hexit_str[i - 1] << 4;
   959              }
   960          }
   961
   962          memset(valuep, 0, val_idx);
   963
   964  free:
   965          free(hexit_str);
   966          return err;
   967      }
   968
   969      errno = 0;
   970      integer = strtoull(s, tail, 0);
   971      if (errno) {
   972          return errno;
   973      }
   974
   975      for (i = field_width - 1; i >= 0; i--) {
   976          valuep[i] = integer;
   977          integer >>= 8;
   978      }
